export const isPointInsideContour = (point: Point, partGeometry: PartGeometry): boolean => {
    const { bbox, entities } = partGeometry;
    if (!bbox || !entities) return false;

    if (point.x < bbox.minX || point.x > bbox.maxX || point.y < bbox.minY || point.y > bbox.maxY) {
        return false;
    }

    let intersections = 0;
    const rayIntersectsSegment = (p: Point, a: Point, b: Point): boolean => {
        if ((a.y > p.y) !== (b.y > p.y)) {
            const intersectX = a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y);
            if (intersectX > p.x) return true;
        }
        return false;
    };

    for (const entity of entities) {
        switch (entity.type) {
            case 'LWPOLYLINE': {
                const vertices = entity.vertices;
                for (let i = 0; i < vertices.length; i++) {
                    const p1 = vertices[i];
                    const p2 = vertices[(i + 1) % vertices.length];
                    if (!entity.closed && i === vertices.length - 1) continue;
                    if (rayIntersectsSegment(point, p1, p2)) intersections++;
                }
                break;
            }
            case 'LINE': {
                if (rayIntersectsSegment(point, entity.start, entity.end)) intersections++;
                break;
            }
            // Упрощенная проверка для кругов и дуг в контексте попадания точки
            case 'CIRCLE': {
                const dx = point.x - entity.center.x;
                const dy = point.y - entity.center.y;
                if (Math.sqrt(dx * dx + dy * dy) <= entity.radius) intersections++;
                break;
            }
        }
    }
    return intersections % 2 !== 0;
};

export const getRotatedExtents = (part: any, rotation: number, tools: Tool[]) => {
    const rad = (rotation * Math.PI) / 180;
    const cos = Math.abs(Math.cos(rad));
    const sin = Math.abs(Math.sin(rad));

    // Базовые габариты на основе геометрии
    const width = part.geometry.width * cos + part.geometry.height * sin;
    const height = part.geometry.width * sin + part.geometry.height * cos;

    // Смещение начала координат
    let ox = 0;
    let oy = 0;
    const r = (rotation % 360 + 360) % 360;
    if (r === 90) ox = part.geometry.height;
    else if (r === 180) { ox = part.geometry.width; oy = part.geometry.height; }
    else if (r === 270) oy = part.geometry.width;

    return { width, height, ox, oy };
};

