        setToasts(prev => prev.filter(t => t.id !== id));
    };

    const processedGeometry = useMemo(() => activePart ? getGeometryFromEntities(activePart) : null, [activePart]);

    const { svgRef, viewBox, setViewBox, isDragging, getPointFromEvent, panZoomHandlers } = usePanAndZoom({ x: -10, y: -600, width: 1000, height: 800 });

    const { handleFileUpload } = useFileImport({ tools, setMode, setActivePart, addToast });

    const selectedTool = useMemo(() => tools.find(t => t.id === selectedToolId) || null, [tools, selectedToolId]);

    const { handleCanvasClick, punchCreationStep, punchCreationPoints } = useManualPunch({
        activePart,
        activePartProcessedGeometry: processedGeometry,
        selectedTool,
        manualPunchMode,
        punchOrientation,
        punchOffset,
        snapMode,
        nibbleSettings,
        destructSettings,
        onAddPunches: (newPunches) => {
            if (!activePart) return;
            const punchesWithIds = newPunches.map(p => ({ ...p, id: generateId() }));
            setActivePart({ ...activePart, punches: [...activePart.punches, ...punchesWithIds] });
        },
        setSelectedPunchId
    });

    // Рендеринг в зависимости от режима
    const renderContent = () => {
        switch (mode) {
            case AppMode.PartLibrary:
                return <PartLibraryView parts={parts} tools={tools} onLoadPart={(p) => { setActivePart(p); setMode(AppMode.PartEditor); }} onDeletePart={(id) => setParts(parts.filter(p => p.id !== id))} onUpdatePart={(up) => setParts(parts.map(p => p.id === up.id ? up : p))} />;
            case AppMode.ToolLibrary:
                return <ToolLibraryView tools={tools} onSaveTool={(t) => setTools(tools.some(x => x.id === t.id) ? tools.map(x => x.id === t.id ? t : x) : [...tools, { ...t, id: generateId() }])} onDeleteTool={(id) => setTools(tools.filter(t => t.id !== id))} />;
            case AppMode.TurretSetup:
                return <TurretSetupView tools={tools} setTools={setTools} layouts={turretLayouts} setLayouts={setTurretLayouts} />;
            case AppMode.MachineSetup:
                return <MachineSetupView settings={machineSettings} onUpdate={setMachineSettings} />;
            case AppMode.ScriptLibrary:
                return <ScriptLibraryView scripts={scripts} tools={tools} parts={parts} onSaveScript={(s) => setScripts(scripts.map(x => x.id === s.id ? s : x))} onDeleteScript={(id) => setScripts(scripts.filter(s => s.id !== id))} onCreatePart={(p) => setParts([...parts, p])} onBatchProcess={(np) => setParts([...parts, ...np])} />;
            default:
                return (
                    <div className="flex flex-1 overflow-hidden">
                        <Sidebar 
                            mode={mode} parts={parts} activePart={activePart} tools={tools} activeNest={nests[0]}
                            onFileUpload={handleFileUpload}
                            manualPunchMode={manualPunchMode} setManualPunchMode={setManualPunchMode}
                            selectedToolId={selectedToolId} setSelectedToolId={setSelectedToolId}
                            selectedPunchId={selectedPunchId} setSelectedPunchId={setSelectedPunchId}
                            punchOrientation={punchOrientation} setPunchOrientation={setPunchOrientation}
                            snapMode={snapMode} setSnapMode={setSnapMode}
                            punchOffset={punchOffset} setPunchOffset={setPunchOffset}
                            nibbleSettings={nibbleSettings} setNibbleSettings={setNibbleSettings}
                            destructSettings={destructSettings} setDestructSettings={setDestructSettings}
                            onDeletePunch={(ids) => { if (!activePart) return; const idList = Array.isArray(ids) ? ids : [ids]; setActivePart({ ...activePart, punches: activePart.punches.filter(p => !idList.includes(p.id)) }); }}
                            onUpdatePunch={(id, up) => { if (!activePart) return; setActivePart({ ...activePart, punches: activePart.punches.map(p => p.id === id ? { ...p, ...up } : p) }); }}
                            onClearAllPunches={() => activePart && setActivePart({ ...activePart, punches: [] })}
                            onUpdateActivePart={(up) => activePart && setActivePart({ ...activePart, ...up })}
                            onClosePart={() => setActivePart(null)}
                            onSavePartAsStatic={() => { if (activePart) setParts([...parts, { ...activePart, id: generateId() }]); addToast("Деталь сохранена в библиотеку", "success"); }}
                            onSavePartAsScript={() => addToast("Функция в разработке", "info")}
                            teachMode={false} setTeachMode={() => {}} onSaveTeachCycle={() => {}} teachCycles={teachCycles} onDeleteTeachCycle={(id) => setTeachCycles(teachCycles.filter(c => c.id !== id))}
                            onOpenTurretView={() => setMode(AppMode.TurretSetup)}
                            activePartId={activePart?.id || null} setActivePartId={() => {}} onDeletePart={() => {}} onCyclePunchOrientation={() => {}}
                        />
                        <CanvasArea 
                            mode={mode} activePart={activePart} processedGeometry={processedGeometry} 
                            activeNest={nests[0]} tools={tools} parts={parts}
                            svgRef={svgRef} viewBox={viewBox} setViewBox={setViewBox}
                            isDragging={isDragging} getPointFromEvent={getPointFromEvent}
                            panZoomHandlers={{ ...panZoomHandlers, onMouseUp: (e) => { panZoomHandlers.onMouseUp(e); if (!isDragging) handleCanvasClick(getPointFromEvent(e)); } }}
                            onOpenAutoPunchSettings={() => setShowAutoToolModal(true)}
                            punchCreationStep={punchCreationStep} punchCreationPoints={punchCreationPoints}
                            manualPunchMode={manualPunchMode} selectedToolId={selectedToolId}
                            selectedPunchId={selectedPunchId} onSelectPunch={setSelectedPunchId}
                            placementReference={PlacementReference.Center} placementSide={PlacementSide.Outside}
                            punchOrientation={punchOrientation} punchOffset={punchOffset} snapMode={snapMode}
                            nibbleSettings={nibbleSettings}
                        />
                        <RightPanel 
                            tools={tools} selectedToolId={selectedToolId} setSelectedToolId={setSelectedToolId}
                            onOpenTurretView={() => setMode(AppMode.TurretSetup)}
                            isNestingMode={mode === AppMode.Nesting} activeNest={nests[0]}
                            activeSheetIndex={0} setActiveSheetIndex={() => {}} allParts={parts}
                            simulationStep={0} totalSimulationSteps={0} isSimulating={false} simulationSpeed={1}
                            onToggleSimulation={() => {}} onStopSimulation={() => {}} onStepChange={() => {}} onSpeedChange={() => {}}
                            optimizedOperations={null}
                        />
                    </div>
                );
        }
    };

    return (
        <div className="flex flex-col h-full font-sans relative">
            <Header mode={mode} setMode={setMode} onGenerateGCode={() => {}} onOptimizePath={() => {}} onOpenTurretConfig={() => setMode(AppMode.TurretSetup)} />
            {renderContent()}
            <ToastContainer toasts={toasts} removeToast={removeToast} />
            <ConfirmationModal state={confirmationState} onCancel={closeConfirmation} />
            {showAutoToolModal && <AutoPunchSettingsModal onClose={() => setShowAutoToolModal(false)} onApply={() => setShowAutoToolModal(false)} turretLayouts={turretLayouts} />}
        </div>
    );
};

export default App;

/**
 * Shared Global Types
 * Содержит базовые контракты данных системы.
 */
export interface Point {
  x: number;
  y: number;
}

export interface DxfLwPolyline {
  type: 'LWPOLYLINE';
  vertices: Point[];
  closed: boolean;
}

export interface DxfCircle {
  type: 'CIRCLE';
  center: Point;
  radius: number;
}

export interface DxfArc {
  type: 'ARC';
  center: Point;
  radius: number;
  startAngle: number;
  endAngle: number;
}

export interface DxfLine {
  type: 'LINE';
  start: Point;
  end: Point;
}

export type DxfEntity = DxfLwPolyline | DxfCircle | DxfArc | DxfLine;

export enum ToolShape {
  Circle = 'circle',
  Square = 'square',
  Rectangle = 'rectangle',
  Oblong = 'oblong',
  Special = 'special',
}

export enum PunchType {
  General = 'general',
  Contour = 'contour',
  Starting = 'starting',
  Finishing = 'finishing',
}

export interface Tool {
  id: string;
  name: string;
  shape: ToolShape;
  width: number;
  height: number;
  cornerRadius: number;
  toolSize: string;
  description: string;
  customPath?: string;
  punchType: PunchType;
  stationNumber?: number;
  stationType?: string;
  mtIndex?: number;
  defaultRotation?: number;
  dies: { clearance: number; }[];
  stripperHeight: number;
  punchDepth: number;
  ramSpeed: number;
  acceleration: number;
  operatingMode: string;
  nibblingPriority: number;
  punchPriority: number;
  punchCount: number;
  isAutoIndex: boolean;
  keyAngles: number[];
  optimizingGroup: string;
  awayFromClamps: boolean;
  motionPrinciple: string;
  relievedStripper: '1-sided' | '2-sided' | 'none';
  yProtectionArea: number;
  zoneWidth: number;
  onlyForC5: boolean;
}

export interface PlacedTool {
  id: string;
  toolId: string;
  x: number;
  y: number;
  rotation: number;
  lineId?: string;
}

export interface PartGeometry {
  path: string;
  width: number;
  height: number;
  entities: DxfEntity[];
  bbox: { minX: number; minY: number; maxX: number; maxY: number; };
}

export interface PartMaterial {
    code: string;
    thickness: number;
    dieClearance: number;
}

export interface NestingConstraints {
    allow0_180: boolean;
    allow90_270: boolean;
    initialRotation: number;
    commonLine: boolean;
    canMirror: boolean;
}

export interface PartProfile {
    type: 'flat' | 'L' | 'U';
    orientation: 'vertical' | 'horizontal';
    dims: { a: number; b: number; c: number; };
}

export interface Part {
  id:string;
  name: string;
  geometry: PartGeometry;
  punches: PlacedTool[];
  material: PartMaterial;
  nesting: NestingConstraints;
  faceWidth: number;
  faceHeight: number;
  profile?: PartProfile;
  script?: string;
  customer?: string;
  workOrder?: string;
}

export interface ParametricScript {
    id: string;
    name: string;
    code: string;
    defaultWidth: number;
    defaultHeight: number;
    updatedAt: number;
}

export interface StationConfig {
    id: number;
    type: string; // 'A', 'B', 'C', 'D', 'MT'
    isAutoIndex: boolean;
}

export interface TurretLayout {
    id: string;
    name: string;
    // Mapping: Station Number -> Tool ID (or null)
    toolsSnapshot: Tool[]; 
    stations: StationConfig[];
}

export interface SheetStock {
    id: string;
    width: number;
    height: number;
    quantity: number; // "Reserved" count
    material: string;
    thickness: number;
    cost: number;
    useInNesting: boolean; // For 'selected-only' strategy
}

export enum SheetUtilizationStrategy {
    FirstOnly = 'first-only',
    ListedOrder = 'listed-order',
    SelectedOnly = 'selected-only',
    SmallestFirst = 'smallest-first',
    BestFit = 'best-fit',
    AutoCalculation = 'auto-calculation'
}

export interface NestingSettings {
  availableSheets: SheetStock[];
  activeSheetId: string | null; // Currently selected for editing or primary use

  // Global Sheet Params
  defaultMaterial: string;
  defaultThickness: number;

  // General Params
  partSpacingX: number;
  partSpacingY: number;
  sheetMarginTop: number;
  sheetMarginBottom: number;
  sheetMarginLeft: number;
  sheetMarginRight: number;
  nestingDirection: number; // 0-8 for a 3x3 grid, representing start corner/edge
  clampPositions: number[];
  nestUnderClamps: boolean;
  loadingStopId: number; // 0 = Auto, 1, 2, 3, 4

  // Strategy
  utilizationStrategy: SheetUtilizationStrategy;

  // Optimization
  useCommonLine: boolean;
  vertexSnapping: boolean; // Auto alignment

  // New Flag
  nestAsRectangle: boolean; 
}

export interface PlacedPart {
  id: string;
  partId: string;
  x: number;
  y: number;
  rotation: number;
}

export interface ScheduledPart {
    partId: string;
    quantity: number;
    priority?: number; 
    nesting: NestingConstraints; // Modified to store full nesting config per scheduled item
}

export interface NestResultSheet {
    id: string;
    sheetName: string; // e.g. "Sheet 1"
    stockSheetId: string;
    width: number;
    height: number;
    material: string;
    thickness: number;
    placedParts: PlacedPart[];
    usedArea: number; // Percentage 0-100
    scrapPercentage: number;
    partCount: number;
    quantity: number; // How many of this identical sheet layout
}

export interface NestLayout {
  id: string;
  name: string;
  customer?: string;
  workOrder?: string;
  settings: NestingSettings;
  sheets: NestResultSheet[]; // Multiple resulting sheets
  scheduledParts: ScheduledPart[];
}

export interface AutoPunchSettings {
    // Tool Library Source
    toolSourceType: 'library' | 'turret';
    turretLayoutId?: string;

    // General
    useTeachCycles: boolean; // "Use teach cycles"

    // Punching/Nibbling Properties
    extension: number; // "Extension"
    overlap: number; // "Overlap length"
    scallopHeight: number; // "Scallop height"
    vertexTolerance: number; // "Vertex tolerance"

    // Tool utilization
    minToolUtilization: number; // "Minimum % of tool utilization"

    // Single hit tolerance
    toleranceRound: number; // "Round & Obround"
    toleranceRectLength: number; // "Rectangle length"
    toleranceRectWidth: number; // "Rectangle width"

    // Micro-joints
    microJointsEnabled: boolean; // "Use external micro-joints"
    microJointType: 'vertical' | 'horizontal' | 'auto'; // Updated from 'all' to 'auto'
    microJointLength: number; // "Micro-joint length"
    microJointDistance: number; // "Maximum micro-joint distance"
}

export interface MachineSettings {
    name: string;
    // Travel Limits
    xTravelMax: number;
    xTravelMin: number;
    yTravelMax: number;
    yTravelMin: number;

    // Clamp Protection
    clampProtectionZoneX: number;
    clampProtectionZoneY: number;
    deadZoneY: number; // e.g. -40mm from clamps

    // Speeds (Informational for generic G-code, but used for Time estimation)
    maxSlewSpeed: number; // m/min
    turretRotationSpeed: number; // RPM
}

export interface OptimizerSettings {
    toolSequence: 'global-station' | 'part-by-part';
    pathOptimization: 'shortest-path' | 'x-axis' | 'y-axis'; // Updated
    startCorner: 'bottom-left' | 'bottom-right' | 'top-left' | 'top-right';
    sheetUnloadMode: 'manual' | 'automatic';

    // Updated Logic
    anglePriority: '0-90' | '90-0'; // Logic for angle sorting in Scan modes

    // G-Code Options
    useG76LinearPatterns: boolean; // Use G76 for lines
}

export interface PatternSegment {
    type: 'line' | 'arc';
    length: number; // Chord Length for arc / Distance between p1 and p2
    angleChange: number; // Angle relative to previous segment (or 0 for first)
    // For arcs
    radius?: number; // Needed to distinguish arcs from lines
    sweepAngle?: number;
    arcCenterLeft?: boolean; // True if center is to the Left of vector P1->P2 (CCW turn)
    largeArc?: boolean; // True if arc spans > 180 degrees
}

export interface PatternPunch {
    toolId: string;
    // Relative coordinates to the start of the first segment
    relX: number;
    relY: number;
    relRotation: number;
}

export type CycleSymmetry = 'none' | 'horizontal' | 'vertical' | 'full';

export interface TeachCycle {
    id: string;
    name: string;
    symmetry: CycleSymmetry;
    segments: PatternSegment[];
    punches: PatternPunch[];
    baseAngle?: number; // Normalized absolute angle of the first segment (in radians)
}

